static void settings_simswitch_timer_event_cb(struct _lv_timer_t *timer)
{
    uint32_t        result_type;

    result_type         = (uint32_t) timer->user_data;

    if (settings_simswitch_timer) {
        lv_timer_del(settings_simswitch_timer);
        settings_simswitch_timer = NULL;

        if ((result_type == 3) || (result_type == 4)) {
            alv_am_app_exit_action_all();
            ts_sim_pin_param_init();
            }
        else {
            alv_am_win_jump_action(NULL,"setting_net_sim",NULL);
            }
        }
}


void settings_simswitch_timer_start(void * p_param)
{

    if (settings_simswitch_timer == NULL) {
        settings_simswitch_timer = lv_timer_create(settings_simswitch_timer_event_cb,1500,p_param);

        }

}


